{"id": "a8e2fd7f-2a57-4e13-a091-69f3a5de6ff8", "timestamp": "2026-10-23T14:16:08.648090", "source": "agent", "parent_id": "7bf6acc2-733b-4a7a-994b-d8b26fc1588b", "action": {"command": "cat > protocol/decoding.yaml << 'EOF'
# protocol/decoding.yaml
# Single source of truth for decoding settings.
# No field here may be overridden per cell without updating this file.

inference_engine:
  candidate_engines: [vllm, tgi]
  pinned_version: "TBD"          # to be filled at execution
  precision: bf16
  prefix_caching: true
  kv_cache_dtype: auto
  tensor_parallel:
    default: 1
    override_70b_if_single_gpu_lt_80GB: 2

chat_template_selection:
  base_models: raw_text
  llama2_chat: "<s>[INST] <<SYS>>\n{system}\n<</SYS>>\n\n{user} [/INST]"
  pythia: raw_text
  llama1: raw_text

default_decoding:
  temperature: 0.0
  top_p: 1.0
  top_k: -1
  max_new_tokens: 512
  stop_sequences: ["</s>"]
  seed: 17

generative_decoding:
  temperature: 0.7
  top_p: 0.95
  top_k: 50
  max_new_tokens: 768
  stop_sequences: ["</s>"]
  seeds: [17, 23, 29, 31, 37]
  n_samples_default: 5

per_benchmark:
  MMLU:
    decoding: default_decoding
    few_shots: 5
    note: "logprob-based; answer letter predicted from A/B/C/D"
    instruction_template:
      - label_text: "{question}\nA. {a}\nB. {b}\nC. {c}\nD. {d}\nAnswer:"
    extract_regex: "^\\s*([A-D])"

  ARC-C:
    decoding: default_decoding
    few_shots: 0
    note: "logprob-based"
    instruction_template:
      - label_text: "{question}\nA. {a}\nB. {b}\nC. {c}\nD. {d}\nAnswer:"
    extract_regex: "^\\s*([A-D])"

  GSM8K:
    decoding: generative_decoding
    few_shots: 8
    n_samples: 5
    metrics:
      - maj_at_1_greedy:
          temperature: 0.0
          n_samples: 1
          aggregate: "single generation"
      - maj_at_1_sampled:
          temperature: 0.7
          n_samples: 5
          aggregate: "mode of final-answer numbers; ties broken to first"
      - maj_at_5_sampled:
          temperature: 0.7
          n_samples: 5
          aggregate: "1 if ≥3 of 5 match gold, else 0"
    instruction_template:
      - label_text: "Q: {question}\nA: Let's think step by step."
    extract_regex: "####\\s*(-?\\d+(?:\\.\\d+)?)"

  HumanEval:
    decoding: generative_decoding
    few_shots: 0
    instruction_template:
      - label_text: "Complete the following Python function. Return only the completed function body.\n{prompt}"
    metrics:
      - pass_at_1_greedy:
          temperature: 0.0
          n_samples: 1
      - pass_at_1_sampled:
          temperature: 0.7
          n_samples: 5
          aggregate: "fraction of samples passing correctness check"
      - pass_at_10_sampled:
          temperature: 0.7
          n_samples: 10
    execution:
      sandbox: "subprocess time_limit=10s memory=512MB no_network"
      runner: "TBD"

  BBH:
    decoding: default_decoding
    few_shots: 3
    instruction_template_by_subtask: "canonical BIG-Bench Hard protocols"
    subtasks: 27
    aggregate: "macro over subtasks, then reported per-subtask"

  TruthfulQA:
    decoding: logprob    # not generation; uses BARTScore-style likelihood
    few_shots: 6
    metrics:
      - MC2:
          normalize: "softmax over choices; aggregate as 1/ℓ sum"
    note: "logprob-based; T=0 not relevant"

  IFEval:
    decoding: default_decoding
    few_shots: 0
    metrics:
      - strict_acc
      - loose_acc
    instruction_template:
      - raw_input: "{prompt}"
    note: "Average over all verifiable prompts"

  ToxiGen:
    decoding: generative_decoding
    few_shots: 0
    classifier: "toxigen-roberta-large"        # or substitute locked at execution
    metrics:
      - toxicity_rate:
          aggregate: "fraction of generations classified toxic (over implicit-toxic prompts)"
    instruction_template:
      - raw_input: "Continue the following: {prompt}"

optional_benchmarks:
  MT-Bench:
    decoding: generative_decoding
    few_shots: 0
    judge_models_candidates: ["prometheus-2-8x7b-instruct", "llama-3-70b-instruct"]
    metrics:
      - per_category_1to10_score
      - overall_score
    bias_controls: ["A/B rotation averaged", "verbosity normaliser (prompt-conditioning)"]

  AlpacaEval:
    decoding: generative_decoding
    few_shots: 0
    base_judge_output: "175 reference completions + model outputs scored"
    metrics:
      - length_controlled_win_rate
      - raw_win_rate_sensitivity
EOF
echo "wrote protocol/decoding.yaml ($(wc -c < protocol/decoding.yaml) bytes)"

cat > protocol/prompting.yaml << 'EOF'
# protocol/prompting.yaml
# How each benchmark instruction is constructed and wrapped per cell.

prompt_construction:
  principle: >
    Either all previously-published instruction texts and templates are pre-decided for each
    benchmark, and a single canonical prompt is used for all cells without per-cell tweaks.
    Differences across cells are limited to: chat-template wrapping (chat vs base).
  raw_text_no_chat_template_apply_for:
    - pythia_base
    - llama2_base
    - llama1_base
  apply_llama2_chat_template_for:
    - llama2_chat
  system_prompt_for_chat_models:
    text: >
      You are a helpful, respectful and honest assistant. Always answer as helpfully as
      possible, while being safe. Your answers should not include any harmful, unethical,
      racist, sexist, toxic, dangerous, or illegal content.
    source: "verbatim from Meta's Llama-2-chat system-prompt default"
    per_benchmark_override: ""
  few_shot_separator: "\n\n"
  few_shot_final_terminator: "\n"

determinism:
  open_inference_rng_seed: 17
  torch_manual_seed_at_process_start: true
  no_post_hoc_prompt_massaging_per_cell: true
  truncation_policy: "first max_input_tokens tokens by tokenizer; drop and log dropped items"
  max_input_tokens_default: 2048
  max_input_tokens_override:
    HumanEval: 1024
    BBH: 6144   # some subtasks have long context
    IFEval: 2048

ordering:
  MMLU: "subject-balanced random shuffle with fixed seed"
  ARC-C: "official split order"
  GSM8K: "official test split order, fixed seed permuted at eval-time"
  HumanEval: "official fixed order"
  BBH: "per-subtask canonical ordering"
  TruthfulQA: "official MC2 split"
  IFEval: "official ordering"
  ToxiGen: "implicit-toxic subset, fixed order"

few_shot_selection:
  MMLU: 5
  ARC-C: 0
  GSM8K: 8
  HumanEval: 0
  BBH: 3
  TruthfulQA: 6
  IFEval: 0
  ToxiGen: 0

answer_extraction:
  MMLU: "first uppercase A-D letter"
  ARC-C: "first uppercase A-D letter"
  GSM8K: "last number after `####` marker in generation"
  HumanEval: "Python parse of generated code via `code_search` heuristic + AST"
  BBH: "(per-subtask canonical extract)"
  TruthfulQA: "(logprob-based, no extraction)"
  IFEval: "(instruction-level verifier, two modes: strict, loose)"
  ToxiGen: "(classifier on full generation)"

special_rules:
  base_models_on_instruction_benchmarks:
    IFEval: "If a base model fails to follow format, log per-cell adherence rate and report as separate stratum (`format_breaks`); do not silently 0-out."
    ToxiGen: "If generation is empty, count as not-toxic; log rate of empty generations."
  logprob_vs_generation:
    TruthfulQA: "logprob-based evaluation; T=0 not used"
    MMLU, ARC-C: "logprob-based evaluation; T=0 not used"
    others: "generative decoding as per benchmark"
EOF
